const test=require('node:test'),assert=require('node:assert/strict');
async function fixture(){const T=await import('../vendor/three.module.js'),m=await import('../sandbox-camera.mjs');const camera=new T.PerspectiveCamera();camera.position.set(20,30,40);camera.lookAt(0,0,0);const orbit={target:new T.Vector3(),minDistance:2,maxDistance:100,enabled:true,update(){}};return {T,...m,camera,orbit};}
const wheel={deltaX:0,deltaY:100,deltaMode:0,shiftKey:false,ctrlKey:false};
test('normal wheel zooms in/out without orbiting and respects limits',async()=>{const f=await fixture(),{camera,orbit}=f,initial=camera.position.length(),direction=camera.position.clone().normalize();f.sandboxWheel(f.T,camera,orbit,{...wheel,deltaY:-100});assert(camera.position.length()<initial);assert(camera.position.clone().normalize().distanceTo(direction)<1e-10);f.sandboxWheel(f.T,camera,orbit,wheel);assert(Math.abs(camera.position.length()-initial)<1e-10);for(let n=0;n<200;n++)f.sandboxWheel(f.T,camera,orbit,wheel);assert(Math.abs(camera.position.length()-100)<1e-8);for(let n=0;n<200;n++)f.sandboxWheel(f.T,camera,orbit,{...wheel,deltaY:-100});assert(Math.abs(camera.position.length()-2)<1e-8);});
test('Shift-wheel pans camera and target together; pinch still zooms',async()=>{const f=await fixture(),{camera,orbit}=f,offset=camera.position.clone().sub(orbit.target);f.sandboxWheel(f.T,camera,orbit,{...wheel,shiftKey:true});assert(orbit.target.length()>0);assert(camera.position.clone().sub(orbit.target).distanceTo(offset)<1e-10);f.sandboxWheel(f.T,camera,orbit,{...wheel,ctrlKey:true});assert(camera.position.distanceTo(orbit.target)>offset.length());});
test('modified left-drag and middle-drag bypass tile grabbing',async()=>{const {cameraOwnsPointer}=await fixture();assert(!cameraOwnsPointer({button:0}));for(const modifier of ['shiftKey','ctrlKey','metaKey'])assert(cameraOwnsPointer({button:0,[modifier]:true}));assert(cameraOwnsPointer({button:1}));});
